\[
\begin{aligned}
Q_{in}
&=C_p(F_xT|_x+F_yT|_y+F_zT|_z)\\[6pt]
&=C_p\left(\rho\Delta y\Delta z\,v_xT|_x+\rho\Delta z\Delta x\,v_yT|_y+\rho\Delta x\Delta y\,v_zT|_z\right)\\[6pt]
&=\rho C_p\left(\Delta y\Delta z\,v_xT|_x+\Delta z\Delta x\,v_yT|_y+\Delta x\Delta y\,v_zT|_z\right)
\end{aligned}
\]

\[
\begin{aligned}
Q_{out}
&=-C_p(F_xT|_{x+\Delta x}+F_yT|_{y+\Delta y}+F_zT|_{z+\Delta z})\\[6pt]
&=-C_p\left(\rho\Delta y\Delta z\,v_xT|_{x+\Delta x}+\rho\Delta z\Delta x\,v_yT|_{y+\Delta y}+\rho\Delta x\Delta y\,v_zT|_{z+\Delta z}\right)\\[6pt]
&=-\rho C_p\left(\Delta y\Delta z\,v_xT|_{x+\Delta x}+\Delta z\Delta x\,v_yT|_{y+\Delta y}+\Delta x\Delta y\,v_zT|_{z+\Delta z}\right)
\end{aligned}
\]

\[
\begin{aligned}
Q_{in}
&=\Delta y\Delta z\,q_x+\Delta z\Delta x\,q_y+\Delta x\Delta y\,q_z\\[6pt]
&=-\Delta y\Delta z\,k\left.\frac{dT}{dx}\right|_x
-\Delta z\Delta x\,k\left.\frac{dT}{dy}\right|_y
-\Delta x\Delta y\,k\left.\frac{dT}{dz}\right|_z
\end{aligned}
\]

\[
\begin{aligned}
Q_{out}
&=-\Delta y\Delta z\,q_{x+\Delta x}
-\Delta z\Delta x\,q_{y+\Delta y}
-\Delta x\Delta y\,q_{z+\Delta z}\\[6pt]
&=\Delta y\Delta z\,k\left.\frac{dT}{dx}\right|_{x+\Delta x}
+\Delta z\Delta x\,k\left.\frac{dT}{dy}\right|_{y+\Delta y}
+\Delta x\Delta y\,k\left.\frac{dT}{dz}\right|_{z+\Delta z}
\end{aligned}
\]

\[
\begin{aligned}
\rho C_p\frac{T_{t+\Delta t}-T_t}{\Delta t}\Delta x\Delta y\Delta z
&={}\rho C_p\left(
\Delta y\Delta z\,v_xT|_x
+\Delta z\Delta x\,v_yT|_y
+\Delta x\Delta y\,v_zT|_z
\right)\\[6pt]
&-\rho C_p\left(
\Delta y\Delta z\,v_xT|_{x+\Delta x}
+\Delta z\Delta x\,v_yT|_{y+\Delta y}
+\Delta x\Delta y\,v_zT|_{z+\Delta z}
\right)\\[6pt]
&-\Delta y\Delta z\,k\left.\frac{dT}{dx}\right|_x
-\Delta z\Delta x\,k\left.\frac{dT}{dy}\right|_y
-\Delta x\Delta y\,k\left.\frac{dT}{dz}\right|_z\\[6pt]
&+\Delta y\Delta z\,k\left.\frac{dT}{dx}\right|_{x+\Delta x}
+\Delta z\Delta x\,k\left.\frac{dT}{dy}\right|_{y+\Delta y}
+\Delta x\Delta y\,k\left.\frac{dT}{dz}\right|_{z+\Delta z}
\end{aligned}
\]

\[
\begin{aligned}
\rho C_p\frac{T_{t+\Delta t}-T_t}{\Delta t}
&={}\rho C_p\left(
\frac{v_x|_xT|_x}{\Delta x}
+\frac{v_y|_yT|_x}{\Delta y}
+\frac{v_z|_zT|_x}{\Delta z}
\right)\\[6pt]
&-\rho C_p\left(
\frac{v_x|_{x+\Delta x}T|_{x+\Delta x}}{\Delta x}
+\frac{v_y|_{y+\Delta y}T|_{x+\Delta x}}{\Delta y}
+\frac{v_z|_{z+\Delta z}T|_{x+\Delta x}}{\Delta z}
\right)\\[6pt]
&-k\frac{\left.\frac{dT}{dx}\right|_x}{\Delta x}
-k\frac{\left.\frac{dT}{dx}\right|_y}{\Delta y}
-k\frac{\left.\frac{dT}{dx}\right|_z}{\Delta z}\\[6pt]
&+k\frac{\left.\frac{dT}{dx}\right|_{x+\Delta x}}{\Delta x}
+k\frac{\left.\frac{dT}{dx}\right|_{y+\Delta y}}{\Delta y}
+k\frac{\left.\frac{dT}{dx}\right|_{z+\Delta z}}{\Delta z}
\end{aligned}
\]

\[
\begin{aligned}
&\rho C_p\frac{T_{t+\Delta t}-T_t}{\Delta t}\\[6pt]
&+\rho C_p\left(
\frac{v_x|_{x+\Delta x}T|_{x+\Delta x}-v_x|_xT|_x}{\Delta x}
\right)\\[6pt]
&+\rho C_p\left(
\frac{v_y|_{y+\Delta y}T|_{y+\Delta y}-v_y|_yT|_y}{\Delta y}
\right)\\[6pt]
&+\rho C_p\left(
\frac{v_z|_{z+\Delta z}T|_{x+\Delta x}-v_z|_zT|_z}{\Delta z}
\right)\\[6pt]
&=k\left(
\frac{\left.\frac{dT}{dx}\right|_{x+\Delta x}-\left.\frac{dT}{dx}\right|_x}{\Delta x}
+\frac{\left.\frac{dT}{dy}\right|_{y+\Delta y}-\left.\frac{dT}{dy}\right|_y}{\Delta y}
+\frac{\left.\frac{dT}{dz}\right|_{z+\Delta z}-\left.\frac{dT}{dz}\right|_z}{\Delta z}
\right)
\end{aligned}
\]
